//! 🧪️ Actual original host dispatch preserves retained tags and bounded roster decisions through physical native closure.
use super::*;
use semio_framework_job::*;
use semio_framework_tool_machine::{ScrubLedger,ScrubInput,ToolAbortReason,ScrubPhase,OriginalScrubLedgerClose};
use semio_framework_value::{RetainedCloneStep,RetainedCloneGrant,RetainedCloneProgress};
use semio_ui_locale::{Locale,Terminology};
use semio_plugin_job_receiving::original_steps::{built,retired,retired_poll};
/// 🪪️ Admits the decoder's Source loan and return table first, because settled constructions are funded against an already admitted decoder.
/// 🧮️ The per-turn grant the largest settled construction of this suite needs (its tag registry backing), taken from the framework's own settled quote.
/// 📐️ The nesting depth the test caller's stock grants; depth bounds one effect, so a turn is granted the stock's whole depth.
const STOCK_DEPTH:usize=4096;
fn grant()->RetainedCloneGrant{let registry=semio_plugin_ownership::bounded_ownership::ARTIFACT_LIVE_OUTPUT_SLOTS*size_of::<(u64,ToolTag)>();let owner=(2*size_of::<OriginalScrubHost<String>>()).max(size_of::<OriginalScrubDispatch<String>>());let size=registry.max(owner);let demand=OriginalConstructionDemand{items:1,copy_bytes:2*size,capacity_bytes:size,release_bytes:registry,depth:1};RetainedCloneGrant{maximum_depth:STOCK_DEPTH,..original_construction_settled_turn_quote::<Box<u8>>(demand,1).expect("bounded construction quote").0}}
fn caller()->OriginalJobFixtureCaller{OriginalJobFixtureCaller::admit(OperationId(9061),Generation(17),RetainedCloneGrant{maximum_items:1<<24,maximum_copy_bytes:1<<24,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24,maximum_depth:STOCK_DEPTH},default_now_us,u64::MAX,1<<24)}
fn turn<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant,run:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(g,decoder,run));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));result.unwrap()}
/// 🔁️ What a turn of this grant bills with no business: the origin refresh of the decoder's table, which a denied business step must not add to.
fn service(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant)->semio_framework_value::RetainedCloneProgress{turn(caller,decoder,g,|_|Ok(()));caller.receipt()}
fn denied(d:RetirementDemand)->Vec<RetainedCloneGrant>{let mut rows=vec![RetainedCloneGrant{maximum_items:0,..grant()}];if d.copy_bytes>0{rows.push(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..grant()})}if d.capacity_bytes>0{rows.push(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..grant()})}if d.depth>0{rows.push(RetainedCloneGrant{maximum_depth:d.depth-1,..grant()})}rows}
fn seed(row:&serde_json::Value)->ScrubLedger<String>{let mut ledger=ScrubLedger::default();for(window,gesture)in row["open"].as_object().unwrap(){let mut input=Some(ScrubInput::Tick{gesture:gesture.as_str().unwrap().into(),leaves:vec![window.clone()]});ledger.send(window,"fixture#press",&semio_framework::kernel::ActorId("actor".into()),"base",&mut input,semio_framework::kernel::HybridLogicalTimestamp{actor:0,physical_ms:1,logical:0}).unwrap();}ledger}
fn tag(row:&serde_json::Value)->Option<ToolTag>{let row=&row["tag"];if row.is_null(){return None}let gesture=row["gesture"].as_str().unwrap().into();Some(ToolTag::Scrub(ScrubTag{window:row["window"].as_str().unwrap().into(),tool:"fixture#press".into(),phase:if row["abort"].as_bool().unwrap(){ScrubPhase::Abort{gesture,reason:ToolAbortReason::Blur}}else{ScrubPhase::Tick{gesture}}}))}
fn view(row:&serde_json::Value)->semio_framework::ViewModel{semio_framework::ViewModel{window_instances:row["roster"].as_array().unwrap().iter().map(|window|semio_framework::ViewWindowInstance{id:window.as_str().unwrap().into(),window_kind_id:"fixture".into()}).collect(),..semio_framework::ViewModel::new(Locale::En,Terminology::Native)}}
fn release_dispatch(owner:&mut Option<Box<OriginalScrubDispatch<String>>>,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){assert!(owner.as_ref().unwrap().terminal_is_empty());let d=OriginalScrubDispatch::<String>::shell_close_demands();turn(caller,decoder,grant(),|cx|cx.with_original_retirement(|cx|{retired(cx,d,|_|{owner.take();Ok(RetainedCloneStep::Complete(receipt(d)))})?;Ok(())}));}
fn finish(mut ledger:ScrubLedger<String>,tag:&mut Option<ToolTag>,mut caller:OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){
 let mut residue=ControlledRetirement::retain(tag.take());while !residue.terminal_is_empty(){let d=residue.next_demand(grant().maximum_copy_bytes).unwrap();turn(&mut caller,decoder,grant(),|cx|cx.with_original_retirement(|cx|{retired_poll(cx,d,|effect|residue.step(grant().maximum_copy_bytes,effect))?;Ok(())}));}
 let mut closing=None;turn(&mut caller,decoder,grant(),|cx|cx.with_original_retirement(|cx|{assert!(OriginalScrubLedgerClose::admit(&mut ledger,&mut closing,cx)?);Ok(())}));for _ in 0..65536{if closing.as_ref().unwrap().terminal_is_empty(){let d=closing.as_ref().unwrap().shell_close_demands();turn(&mut caller,decoder,grant(),|cx|cx.with_original_retirement(|cx|{retired(cx,d,|_|{closing.take();Ok(RetainedCloneStep::Complete(receipt(d)))})?;Ok(())}));break}turn(&mut caller,decoder,grant(),|cx|cx.with_original_retirement(|cx|{closing.as_mut().unwrap().close_step(&mut ledger,cx)?;Ok(())}));}assert!(closing.is_none());
 while !decoder.terminal_is_empty(){let d=decoder.retirement_demands(grant().maximum_copy_bytes).unwrap();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(grant(),|cx|cx.with_original_retirement(|cx|{decoder.close_on_source(cx)?;Ok(())})));result.unwrap();let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));}caller.retire(grant());
}
#[test]
fn original_scrub_host_roster_and_abort_match_independent_cases_without_cloning_or_ambient_custody(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();
 for row in law["cases"].as_array().unwrap(){let mut ledger=seed(row);let view=view(row);let mut tag=tag(row);let mut caller=caller();let mut decoder=caller.admitted_decoder();let mut owner=None;let mut admission=OriginalConstructionAdmission::default();let mut decision=None;
  for grant in [RetainedCloneGrant{maximum_items:0,..grant()},RetainedCloneGrant{maximum_capacity_bytes:0,..grant()},RetainedCloneGrant{maximum_copy_bytes:0,..grant()},RetainedCloneGrant{maximum_depth:0,..grant()}]{let expected=service(&mut caller,&mut decoder,grant);turn(&mut caller,&mut decoder,grant,|cx|{assert!(!OriginalScrubDispatch::admit(&ledger,Some(&view),row["frozen"].as_bool().unwrap_or(false),&mut admission,&mut owner,cx)?);Ok(())});assert!(owner.is_none());assert_eq!(caller.receipt(),expected);}
  while owner.is_none(){turn(&mut caller,&mut decoder,grant(),|cx|{OriginalScrubDispatch::admit(&ledger,Some(&view),row["frozen"].as_bool().unwrap_or(false),&mut admission,&mut owner,cx)?;Ok(())});assert!(owner.is_some()||caller.receipt()!=RetainedCloneProgress::default(),"funded host source admission made no progress");}
  for index in 0..65536{if owner.as_ref().unwrap().terminal_is_empty(){break}let d=owner.as_ref().unwrap().demands(&ledger,grant().maximum_copy_bytes).unwrap();for grant in denied(d){let before=ledger.source_revision();turn(&mut caller,&mut decoder,grant,|cx|{assert!(!owner.as_mut().unwrap().advance(&mut ledger,Some(&view),&mut tag,&mut decision,cx)?);Ok(())});assert_eq!(caller.receipt(),Default::default());assert_eq!(ledger.source_revision(),before);assert!(decision.is_none());}turn(&mut caller,&mut decoder,grant(),|cx|{owner.as_mut().unwrap().advance(&mut ledger,Some(&view),&mut tag,&mut decision,cx)?;Ok(())});assert!(index<65535);}
  let actual=serde_json::json!({"open":ledger.windows().collect::<Vec<_>>(),"closed":ledger.closed_presses().collect::<std::collections::BTreeMap<_,_>>(),"settled":decision.unwrap(),"tagRetained":tag.is_some()});assert_eq!(actual,row["expected"],"{}",row["name"]);println!("[SCRUB-HOST] {}",serde_json::json!({"name":row["name"],"actual":actual}));release_dispatch(&mut owner,&mut caller,&mut decoder);finish(ledger,&mut tag,caller,&mut decoder);
 }
}
#[test]
fn original_scrub_host_cancelled_prefix_preserves_source_and_retires_accepted_tag(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let row=&law["cases"][1];
 for cut in law["cancelCuts"].as_array().unwrap(){let mut ledger=seed(row);let view=view(row);let mut tag=tag(row);let mut caller=caller();let mut decoder=caller.admitted_decoder();let mut owner=None;let mut admission=OriginalConstructionAdmission::default();let mut decision=None;while owner.is_none(){turn(&mut caller,&mut decoder,grant(),|cx|{OriginalScrubDispatch::admit(&ledger,Some(&view),row["frozen"].as_bool().unwrap_or(false),&mut admission,&mut owner,cx)?;Ok(())});assert!(owner.is_some()||caller.receipt()!=RetainedCloneProgress::default(),"funded host source admission made no progress");}for _ in 0..cut.as_u64().unwrap(){turn(&mut caller,&mut decoder,grant(),|cx|{owner.as_mut().unwrap().advance(&mut ledger,Some(&view),&mut tag,&mut decision,cx)?;Ok(())});assert!(decision.is_none());}caller.cancel().cancel_now();for index in 0..65536{if owner.as_ref().unwrap().terminal_is_empty(){break}turn(&mut caller,&mut decoder,grant(),|cx|cx.with_original_retirement(|cx|{owner.as_mut().unwrap().close_step(&mut ledger,cx)?;Ok(())}));assert!(index<65535);}assert!(decision.is_none());assert_eq!(ledger.windows().collect::<Vec<_>>(),vec!["w1","w2"]);release_dispatch(&mut owner,&mut caller,&mut decoder);finish(ledger,&mut tag,caller,&mut decoder);println!("[SCRUB-HOST-CANCEL] {}",serde_json::json!({"cut":cut,"unchanged":true,"sourceClosed":true}));}
}

#[test]
fn original_operation_tag_registry_preserves_every_admitted_owner_when_full(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let row=&law["registry"];let limit=row["limit"].as_u64().unwrap();assert_eq!(limit as usize,semio_plugin_ownership::bounded_ownership::ARTIFACT_LIVE_OUTPUT_SLOTS);let mut machines=ToolMachineRuntime::<(),String>::default();let mut caller=caller();let mut decoder=caller.admitted_decoder();let d=moved(2*size_of::<u64>());
 for operation in 0..limit{
  let mut input=Some(ToolTag::Scrub(ScrubTag{window:"w".into(),tool:"fixture#tag".into(),phase:ScrubPhase::Tick{gesture:format!("g{operation}")}}));let mut pending=None;
  turn(&mut caller,&mut decoder,RetainedCloneGrant{maximum_items:0,..grant()},|cx|{assert!(!admit_original_tagged(&mut machines,operation,&mut input,&mut pending,d,cx,||operation)?);Ok(())});assert!(input.is_some()&&pending.is_none());assert_eq!(caller.receipt(),Default::default());
  while pending.is_none(){turn(&mut caller,&mut decoder,grant(),|cx|{admit_original_tagged(&mut machines,operation,&mut input,&mut pending,d,cx,||operation)?;Ok(())});assert!(pending.is_some()||caller.receipt()!=RetainedCloneProgress::default(),"funded registry admission made no progress for operation {operation}");}
  assert!(input.is_none());assert_eq!(pending,Some(operation));
 }
 let mut input=Some(ToolTag::Scrub(ScrubTag{window:"w".into(),tool:"fixture#tag".into(),phase:ScrubPhase::Tick{gesture:"overflow".into()}}));let pointer=match input.as_ref().unwrap(){ToolTag::Scrub(tag)=>tag.phase.gesture().as_ptr(),_=>unreachable!()};let mut pending=None;let mut called=false;
 let expected=service(&mut caller,&mut decoder,grant());turn(&mut caller,&mut decoder,grant(),|cx|{assert!(!admit_original_tagged(&mut machines,limit,&mut input,&mut pending,d,cx,||{called=true;limit})?);Ok(())});assert!(!called&&pending.is_none());assert_eq!(caller.receipt(),expected);assert_eq!(machines.operations.len(),limit as usize);assert_eq!(match input.as_ref().unwrap(){ToolTag::Scrub(tag)=>tag.phase.gesture().as_ptr(),_=>unreachable!()},pointer);
 let first=matches!(machines.operation_tag(0),Some(ToolTag::Scrub(ScrubTag{phase:ScrubPhase::Tick{gesture},..}))if gesture=="g0");assert!(first);
 let selected=row["takeOperation"].as_u64().unwrap();let mut taken=None;let mut admission=OriginalConstructionAdmission::default();let d=moved(machines.operations.len()*size_of::<(u64,ToolTag)>()+2*size_of::<Option<ToolTag>>());
 turn(&mut caller,&mut decoder,grant(),|cx|{built(cx,&mut admission,&mut taken,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:0,release_bytes:0,depth:d.depth},||Ok((machines.take_operation(selected).unwrap(),receipt(d))))?;Ok(())});assert!(matches!(taken.as_ref(),Some(ToolTag::Scrub(ScrubTag{phase:ScrubPhase::Tick{gesture},..}))if gesture==&format!("g{selected}")));assert!(machines.take_operation(selected).is_none());
 let actual=serde_json::json!({"admitted":limit,"fullPreservesOriginal":true,"firstRetained":first,"taken":selected,"secondTake":false,"remaining":machines.operations.len(),"pendingOwned":true});assert_eq!(actual,row["expected"]);println!("[TAG-REGISTRY] {actual}");
 let mut owners=None;let d=moved(2*size_of::<ControlledRetirement<(Vec<(u64,ToolTag)>,Option<ToolTag>,Option<ToolTag>)>>());
 turn(&mut caller,&mut decoder,grant(),|cx|{built(cx,&mut admission,&mut owners,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:0,release_bytes:0,depth:d.depth},||Ok((ControlledRetirement::retain((std::mem::take(&mut machines.operations),taken.take(),input.take())),receipt(d))))?;Ok(())});
 while !owners.as_ref().unwrap().terminal_is_empty(){let d=owners.as_ref().unwrap().next_demand(grant().maximum_copy_bytes).unwrap();turn(&mut caller,&mut decoder,grant(),|cx|cx.with_original_retirement(|cx|{retired_poll(cx,d,|effect|owners.as_mut().unwrap().step(grant().maximum_copy_bytes,effect))?;Ok(())}));}
 finish(ScrubLedger::default(),&mut None,caller,&mut decoder);
}
